param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'numberformatinfo-readonly-clone-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Decode($Spec,$Encoded){if([object]::ReferenceEquals($Encoded,$null)){$v=$null}elseif($Spec.kind -eq 'int'){$v=[int]$Encoded}elseif($Spec.kind -eq 'array'){$v=[int[]]$Encoded}else{$v=-join [char[]][int[]]$Encoded};return ,$v}
function New-Seed{$n=[Globalization.NumberFormatInfo]::new();foreach($spec in $plan.properties){[Globalization.NumberFormatInfo].GetProperty($spec.name).SetValue($n,(Decode $spec $spec.seed))};return $n}
function Snapshot($N){$values=[ordered]@{};foreach($spec in $plan.properties){$v=[Globalization.NumberFormatInfo].GetProperty($spec.name).GetValue($N);if($spec.kind -eq 'string'){$values[$spec.name]=[int[]][char[]]$v}elseif($spec.kind -eq 'array'){$values[$spec.name]=[int[]]$v}else{$values[$spec.name]=[int]$v}};return [ordered]@{readOnly=$N.IsReadOnly;values=$values}}
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null});actualValue=$(if($e -is [ArgumentOutOfRangeException]){$e.ActualValue}else{$null})}}
$rows=[Collections.Generic.List[object]]::new()
foreach($spec in $plan.properties){for($profileIndex=0;$profileIndex -lt $spec.inputs.Count;$profileIndex++){foreach($mode in @('mutable','readonly','clone')){
 $original=New-Seed;$readOnly=[Globalization.NumberFormatInfo]::ReadOnly($original);if($mode -eq 'mutable'){$target=$original}elseif($mode -eq 'readonly'){$target=$readOnly}else{$target=[Globalization.NumberFormatInfo]$readOnly.Clone()};$before=Snapshot $target
 try{[Globalization.NumberFormatInfo].GetProperty($spec.name).SetValue($target,(Decode $spec $spec.inputs[$profileIndex]));$result=[ordered]@{ok=$true}}catch{$result=Failure $_}
 $rows.Add([ordered]@{property=$spec.name;profile=$profileIndex;mode=$mode;before=$before;result=$result;after=(Snapshot $target);originalAfter=(Snapshot $original);targetIsOriginal=[object]::ReferenceEquals($target,$original);providerSelf=[object]::ReferenceEquals($target.GetFormat([Globalization.NumberFormatInfo]),$target);providerNull=[object]::ReferenceEquals($target.GetFormat($null),$null);providerOther=[object]::ReferenceEquals($target.GetFormat([int]),$null)})
}}}
$clones=[Collections.Generic.List[object]]::new()
foreach($spec in $plan.properties){$original=New-Seed;$readOnly=[Globalization.NumberFormatInfo]::ReadOnly($original);$again=[Globalization.NumberFormatInfo]::ReadOnly($readOnly);$cloneOriginal=[Globalization.NumberFormatInfo]$original.Clone();$cloneReadOnly=[Globalization.NumberFormatInfo]$readOnly.Clone();$before=@((Snapshot $original),(Snapshot $readOnly),(Snapshot $cloneOriginal),(Snapshot $cloneReadOnly));$identity=@((-not [object]::ReferenceEquals($original,$readOnly)),[object]::ReferenceEquals($readOnly,$again),(-not [object]::ReferenceEquals($original,$cloneOriginal)),(-not [object]::ReferenceEquals($readOnly,$cloneReadOnly)),(-not [object]::ReferenceEquals($cloneOriginal,$cloneReadOnly)))
 [Globalization.NumberFormatInfo].GetProperty($spec.name).SetValue($original,(Decode $spec $spec.originalMutation));$afterOriginal=@((Snapshot $original),(Snapshot $readOnly),(Snapshot $cloneOriginal),(Snapshot $cloneReadOnly));[Globalization.NumberFormatInfo].GetProperty($spec.name).SetValue($cloneReadOnly,(Decode $spec $spec.cloneMutation));$afterClone=@((Snapshot $original),(Snapshot $readOnly),(Snapshot $cloneOriginal),(Snapshot $cloneReadOnly));$clones.Add([ordered]@{property=$spec.name;identity=$identity;before=$before;afterOriginal=$afterOriginal;afterClone=$afterClone;cloneType=$cloneReadOnly.GetType().FullName})
}
try{[void][Globalization.NumberFormatInfo]::ReadOnly($null);$nullFactory=[ordered]@{ok=$true}}catch{$nullFactory=Failure $_}
if($rows.Count -ne 870 -or $clones.Count -ne 22){throw 'Wrong readonly/clone matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';rows=$rows.ToArray();clones=$clones.ToArray();nullFactory=$nullFactory;qualification='REPRESENTED_NUMBERFORMATINFO_READONLY_CLONE_PUBLIC_BEHAVIOR_ONLY; ICLONEABLE_INTERFACE_FULL_METADATA_OTHER_FIELDS_CULTURE_SERIALIZATION_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 24 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS NumberFormatInfo readonly/clone: 870 setter cases, 22 clone cases and null factory'
